import type { Metadata } from "next";
import { db } from "@/lib/db";
import { UseCaseLanding, type UseCaseContent } from "@/components/marketing/UseCaseLanding";

export const dynamic = "force-dynamic";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export const metadata: Metadata = {
  title: "VPN Server Hosting — WireGuard & OpenVPN on a VPS",
  description:
    "Run your own private WireGuard or OpenVPN server on a fast NVMe VPS with a dedicated IP and full root. One-click images, from $6.49/mo. Deploy in under a minute.",
  alternates: { canonical: "/vpn-server-hosting" },
  openGraph: {
    type: "article",
    title: "VPN Server Hosting — WireGuard & OpenVPN on a VPS",
    description:
      "Your own private VPN server on an NVMe VPS: WireGuard or OpenVPN one-click images, a dedicated IPv4, and full root access.",
    url: `${APP_URL}/vpn-server-hosting`,
  },
};

const content: UseCaseContent = {
  eyebrow: "VPN hosting",
  title: "Host your own VPN on a",
  highlight: "real VPS",
  sub: "Spin up a private WireGuard or OpenVPN server on your own NVMe VPS — a dedicated IPv4, full root, and no shared exit node. One-click images, from $6.49/mo.",
  intro: [
    "Commercial VPN apps route you through IPs shared with thousands of strangers — the same addresses that get rate-limited, captcha-walled, and blocklisted. When you host your own VPN on a VPS you get a dedicated IPv4 that is yours alone, so services see a stable, clean address you control.",
    "WireGuard and OpenVPN are both recognised one-click images on Nxeon: pick one at deploy and your server boots with the VPN stack in place, ready for you to add peers. WireGuard is the modern, lean choice — a tiny codebase and fast handshakes — while OpenVPN is the battle-tested option with the widest client support.",
    "Because it is a full VPS with root over SSH, this is a real server, not a locked-down appliance. Tune the config, add DNS filtering, route only certain subnets, or run other services alongside the tunnel. Everything sits on enterprise NVMe over a self-healing ZFS mirror in our low-latency Singapore datacenter.",
  ],
  whyTitle: "Built for a private VPN",
  why: [
    { title: "WireGuard or OpenVPN, one click", body: "Both are recognised one-click images. Choose your protocol at deploy and the server comes up with the VPN stack installed and ready to add peers." },
    { title: "A dedicated IPv4 that's yours", body: "Every plan includes a dedicated IPv4, so your tunnel exits from a stable address you alone use — not an IP shared with a crowd of other subscribers." },
    { title: "Full root over SSH", body: "It's your machine. Edit the WireGuard config, rotate keys, add DNS-level ad blocking, or split-tunnel specific routes — nothing is locked down." },
    { title: "Low-latency Singapore node", body: "A single Singapore datacenter means consistent, low-latency routing across Asia-Pacific — ideal if you or your team are based in the region." },
    { title: "DDoS protection + firewall", body: "Always-on network DDoS mitigation and a managed firewall guard the endpoint, so your tunnel stays up even under unwanted attention." },
    { title: "Snapshots before you tinker", body: "Take an instant snapshot before you change the config or upgrade the kernel, and roll back in seconds if a peer setup goes sideways." },
  ],
  steps: [
    { title: "Create your account", body: "Sign up with no credit card required and open the deploy wizard." },
    { title: "Pick WireGuard or OpenVPN + a plan", body: "Select the one-click VPN image and a plan — a small 2 GB server handles a personal or small-team tunnel easily. It's live in under a minute." },
    { title: "Add your first peer", body: "SSH in, generate a client config or QR code for your phone or laptop, and import it into the WireGuard or OpenVPN client." },
    { title: "Connect and verify", body: "Bring the tunnel up and confirm your traffic now exits from your server's dedicated IP. Add more peers whenever you need them." },
  ],
  specNote:
    "A 2 GB Starter comfortably serves a personal VPN or a handful of devices. Move up to Standard (4 GB) for a small team or heavier throughput — and resize any time without a rebuild.",
  faq: [
    { q: "WireGuard or OpenVPN — which should I pick?", a: "Both are one-click images. WireGuard is the modern default: a tiny codebase, very fast handshakes, and excellent mobile battery life. OpenVPN is older and slightly heavier but has the widest client and router support and is easier to push through restrictive networks. If you're unsure, start with WireGuard." },
    { q: "Do I get a dedicated IP for my VPN?", a: "Yes. Every plan includes a dedicated IPv4, so your VPN exits from an address that is yours alone — not shared with other subscribers the way commercial VPN apps work. That means a stable, clean IP you fully control." },
    { q: "How many devices can I connect?", a: "As many as you like — you add peers yourself. A 2 GB Starter easily handles a personal setup or a small household; for a team or higher sustained throughput, choose a larger plan. You can resize vCPU, RAM, and disk any time with no rebuild." },
    { q: "Is this a no-logs VPN?", a: "It's your server, so you decide what is and isn't logged. By default a fresh VPN server keeps only standard system logs, and with full root you can configure logging exactly how you want. We don't inspect your tunnel traffic." },
    { q: "Can I run other things on the same VPS?", a: "Absolutely. With full root you can run a DNS resolver (for network-wide ad blocking), a small web service, or other workloads alongside the VPN — it's a complete server, not a single-purpose box." },
  ],
  related: [
    { label: "VPS hosting", href: "/vps" },
    { label: "Docker hosting", href: "/docker-hosting" },
    { label: "Discord bot hosting", href: "/discord-bot-hosting" },
    { label: "Pricing", href: "/pricing" },
    { label: "Free tools", href: "/tools" },
  ],
